import{_ as a,o as t,c as o,a7 as l}from"./chunks/framework.FWlv_suP.js";const p=JSON.parse('{"title":"ARFlix Data Collection","description":"Official data-collection information for ARFlix.","frontmatter":{"title":"ARFlix Data Collection","description":"Official data-collection information for ARFlix.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-collection/arflix.md","filePath":"data-collection/arflix.md"}'),r={name:"data-collection/arflix.md"};function i(n,e,s,c,d,f){return t(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="arflix-data-collection" tabindex="-1">ARFlix Data Collection <a class="header-anchor" href="#arflix-data-collection" aria-label="Permalink to &quot;ARFlix Data Collection&quot;">​</a></h1><p><strong>Last reviewed:</strong> August 1, 2026</p><h2 id="data-stored-locally" tabindex="-1">Data stored locally <a class="header-anchor" href="#data-stored-locally" aria-label="Permalink to &quot;Data stored locally&quot;">​</a></h2><p>ARFlix stores a local display name, successful-login password hash, and family content preference in localStorage. This is a local content gate, not a cloud account. The plain-text password is not stored or sent to an ARFlix server.</p><h2 id="network-data-processing" tabindex="-1">Network data processing <a class="header-anchor" href="#network-data-processing" aria-label="Permalink to &quot;Network data processing&quot;">​</a></h2><ul><li>TMDb receives searches, filters, media or person identifiers, content-filter parameters, and normal connection metadata for discovery data and images.</li><li>Google receives normal connection metadata when the public AR Collection spreadsheet is loaded.</li><li>YouTube, IMDb, watch providers, image hosts, or <code>wsrv.nl</code> receive requested URLs and connection metadata when their features are used.</li></ul><h2 id="data-collected-by-the-developer" tabindex="-1">Data collected by the developer <a class="header-anchor" href="#data-collected-by-the-developer" aria-label="Permalink to &quot;Data collected by the developer&quot;">​</a></h2><p>ARFlix has no developer-operated analytics, advertising, tracking, account, or telemetry endpoint. The developer does not receive local preferences or search history. Support email contains only what you choose to send.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions can be sent to <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',10)])])}const m=a(r,[["render",i]]);export{p as __pageData,m as default};
